// Bounded writer inventory for raw UNIT76, used by55f10's queue key.
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import java.io.PrintWriter;
public class FindNativeDisplayElevationWrites extends GhidraScript{public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){InstructionIterator it=currentProgram.getListing().getInstructions(true);while(it.hasNext()){Instruction i=it.next();if(i.getNumOperands()==0)continue;String op=i.getDefaultOperandRepresentation(0);if(op.contains(" + 0x76]")&&!i.getMnemonicString().equals("CMP")&&!i.getMnemonicString().equals("TEST")){Function f=currentProgram.getFunctionManager().getFunctionContaining(i.getAddress());out.println(i.getAddress()+" "+i+" FUNCTION "+(f==null?"null":f.getEntryPoint()+" "+f.getName()));}}}}}
